@st.composite
def attributes_list_strategy(draw):
    n = draw(st.integers(min_value=0, max_value=4))
    attrs = [draw(attribute_strategy()) for _ in range(n)]
    if attrs and draw(st.booleans()) and draw(st.booleans()):
        idx = draw(st.integers(min_value=0, max_value=len(attrs) - 1))
        dup_name = attrs[idx].split("=", 1)[0]
        new_val = draw(
            st.text(
                alphabet=st.characters(
                    exclude_characters="<&" + '"' + "'", max_codepoint=0x7E
                ),
                max_size=5,
            )
        )
        attrs.append('%s="%s"' % (dup_name, new_val))
    return attrs


def _render_attrs(attrs):
    return "".join(" " + a for a in attrs)


# ---------------------------------------------------------------------------
# Elements: recursive, name threaded through so open/close tags match.
# ---------------------------------------------------------------------------

def _make_self_closing(name, attrs):
    return "<%s%s/>" % (name, _render_attrs(attrs))


@st.composite
def _leaf_element(draw):
    name = draw(xml_name())
    attrs = draw(attributes_list_strategy())
    return _make_self_closing(name, attrs)


def _content_item(children):
    return st.one_of(
        chardata_strategy(),
        entity_ref_strategy(),
        charref_strategy(),
        cdata_strategy(),
        comment_strategy(),
        pi_strategy(),
        children,
    )


def _extend_element(children):
    @st.composite
    def _build(draw):
        name = draw(xml_name())
        attrs = draw(attributes_list_strategy())
        n_items = draw(st.integers(min_value=0, max_value=4))
        item_strategy = _content_item(children)
        parts = [draw(item_strategy) for _ in range(n_items)]
        return "<%s%s>%s</%s>" % (name, _render_attrs(attrs), "".join(parts), name)

    return _build()


element_strategy = st.recursive(_leaf_element(), _extend_element, max_leaves=16)


# ---------------------------------------------------------------------------
# Deep nesting. Iteration 5 ("deepen"): measurement showed the old
# st.recursive-based deep_element_strategy (max_leaves=100) topped out at
# an observed depth of 6 across 500 documents -- max_leaves is a soft
# average-size hint the underlying "extend or stop" coin flip only
# approaches asymptotically, not a depth floor, and Hypothesis's
# collection-length heuristics generally favour short collections for
# shrink-quality reasons. deep_linear_chain fixes this by flooring the
# chain length at _DEEP_CHAIN_MIN_DEPTH: it is a single Hypothesis-drawn,
# Hypothesis-shrinkable list length (still fully variable, still fully
# shrinkable -- satisfying the "depth must be something Hypothesis can
# vary and shrink" requirement) that is folded into nested tags with a
# loop rather than literal Python recursion, specifically so that a
# drawn depth in the hundreds cannot blow the *generator's own* Python
# recursion limit before it ever reaches the C parser. A linear chain is
# exactly the right-recursive production `Chain -> Tag Chain Tag | eps`;
# list-and-fold is a standard, idiomatic way to express that production.
# deep_element_strategy (bushy-or-deep via st.recursive) is kept for
# structural diversity, it just is no longer the only depth lever.
# ---------------------------------------------------------------------------

_DEEP_CHAIN_MIN_DEPTH = 25
_DEEP_CHAIN_MAX_DEPTH = 500

_deep_name_strategy = st.sampled_from(list("abcdefgh"))


@st.composite
def deep_linear_chain(draw, min_depth=_DEEP_CHAIN_MIN_DEPTH, max_depth=_DEEP_CHAIN_MAX_DEPTH):
    names = draw(st.lists(_deep_name_strategy, min_size=min_depth, max_size=max_depth))
    opens = "".join("<%s>" % n for n in names)
    closes = "".join("</%s>" % n for n in reversed(names))
    return opens + closes


@st.composite
def _deep_leaf(draw):
    name = draw(_deep_name_strategy)
    return "<%s/>" % name


def _deep_extend(children):
    @st.composite
    def _build(draw):
        name = draw(_deep_name_strategy)
        child = draw(children)
        return "<%s>%s</%s>" % (name, child, name)

    return _build()


deep_element_strategy = st.recursive(_deep_leaf(), _deep_extend, max_leaves=100)


@st.composite
def deep_mismatched_doc(draw):
    """A deep, otherwise well-formed chain whose outermost closing tag is
    corrupted, so the mismatch only surfaces after a full deep descent.
    Built on deep_linear_chain (guaranteed depth) rather than the
    st.recursive-based deep_element_strategy, which measurement showed
    reaching a maximum observed depth of only 6 across 500 documents --
    defeating the point of a "deep" mismatch case."""
    body = draw(deep_linear_chain())
    idx = body.rfind("</")
    if idx == -1:
        name = draw(_deep_name_strategy)
        other = draw(_deep_name_strategy.filter(lambda c: c != name))
        return "<%s>%s</%s>" % (name, body, other)
    end = body.find(">", idx)
    if end == -1:
        end = len(body)
    alt = draw(_deep_name_strategy)
    return body[: idx + 2] + alt + body[end:]


def deep_unterminated_doc():
    """A long run of open tags that are never closed at all, floored at
    _DEEP_CHAIN_MIN_DEPTH so this is always genuinely deep when chosen."""
    return st.lists(
        _deep_name_strategy, min_size=_DEEP_CHAIN_MIN_DEPTH, max_size=_DEEP_CHAIN_MAX_DEPTH
    ).map(lambda names: "".join("<%s>" % nm for nm in names))
